namespace ghidra.app.plugin.core.strings;





using docking;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.program.util;
using ghidra.util.table;

public class DefinedStringsContext : DefaultActionContext, DataLocationListContext,
		ProgramLocationSupplierContext {

	private DefinedStringsProvider viewStringsProvider;
	private GhidraTable table;
	private DefinedStringsTableModel tableModel;

	DefinedStringsContext(DefinedStringsProvider provider, GhidraTable table,
			DefinedStringsTableModel tableModel) : base(provider, table)
    {
		this.viewStringsProvider = provider;
		this.table = table;
		this.tableModel = tableModel;
	}

	/* @Override */
	public int getCount() {
		return table.getSelectedRowCount();
	}

	/* @Override */
	public Program getProgram() {
		return viewStringsProvider.getProgram();
	}

	/* @Override */
	public ProgramLocation getLocation() {
		int row = table.getSelectedRow();
		if (row < 0) {
			return null;
		}
		return tableModel.getRowObject(row);
	}

	/* @Override */
	public List<ProgramLocation> getDataLocationList() {
		return getDataLocationList(null);
	}

	/* @Override */
	public List<ProgramLocation> getDataLocationList(Predicate<Data> filter) {
		List<ProgramLocation> result = new();
		int[] selectedRows = table.getSelectedRows();
		foreach (int row in selectedRows) {
			ProgramLocation location = tableModel.getRowObject(row);
			Data data = DataUtilities.getDataAtLocation(location);
			if (passesFilter(data, filter)) {
				result.add(location);
			}
		}
		return result;
	}

	private bool passesFilter(Data data, Predicate<Data> filter) {
		if (data == null) {
			return false;
		}
		if (filter == null) {
			return true;
		}
		return filter.test(data);
	}

	ProgramSelection getProgramSelection() {
		return table.getProgramSelection();
	}

	public int getSelectedRowCount() {
		return table.getSelectedRowCount();
	}

	public Data getSelectedData() {
		int selectedRow = table.getSelectedRow();
		if (selectedRow < 0) {
			return null;
		}
		ProgramLocation location = tableModel.getRowObject(selectedRow);
		return DataUtilities.getDataAtLocation(location);
	}

}
